package com.craftdistrict.block;

import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

/** Generated by tools/generate_police_armory.py; decoration, part, facing. */
final class PoliceArmoryShapes {
    private static final VoxelShape[][][] SHAPES = {
        {
            rotations(Shapes.or(
                Block.box(1.5, 0, 5.5, 14.5, 2, 10.125),
                Block.box(3.125, 2, 6.6875, 12.875, 9, 8)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(0.5, 0, 4, 15.5, 1, 13.5),
                Block.box(1, 1, 11.25, 15, 16, 12.75),
                Block.box(4, 12.25, 6.75, 12, 16, 9.75),
                Block.box(2, 4.125, 8, 14, 12.25, 11.25)).optimize()),
            rotations(Shapes.or(
                Block.box(1, 0, 11.25, 15, 15.75, 12.75),
                Block.box(4, 0, 6.75, 12, 10.75, 9.75),
                Block.box(2, 12, 5, 14, 12.625, 12),
                Block.box(4.75, 12.625, 5.75, 11.25, 15.875, 11.75)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(0.75, 0.75, 14.25, 15.25, 15.25, 16),
                Block.box(2.75, 1.875, 12, 13, 13.625, 14.25)).optimize())
        },
        {
            rotations(Shapes.or(
                Block.box(0.5, 0, 4, 15.5, 1, 13.5),
                Block.box(1, 1, 11.5, 15, 16, 12.75),
                Block.box(2, 3.5, 4.75, 14, 4.125, 11.75),
                Block.box(3, 4.125, 6.25, 13, 16, 8.875)).optimize()),
            rotations(Shapes.or(
                Block.box(1, 0, 11.5, 15, 15.75, 12.75),
                Block.box(3, 0, 6.25, 13, 2.125, 8.875),
                Block.box(8, 2.125, 6.625, 10.125, 14.5, 8.125)).optimize())
        }
    };

    private PoliceArmoryShapes() { }

    static VoxelShape get(int decoration, int part, BlockState state) {
        int turn = switch (state.getValue(BlockStateProperties.HORIZONTAL_FACING)) {
            case EAST -> 1;
            case SOUTH -> 2;
            case WEST -> 3;
            default -> 0;
        };
        return SHAPES[decoration][part][turn];
    }

    private static VoxelShape[] rotations(VoxelShape north) {
        VoxelShape[] result = new VoxelShape[4];
        result[0] = north;
        for (int turn = 1; turn < 4; turn++) {
            VoxelShape rotated = Shapes.empty();
            for (AABB box : result[turn - 1].toAabbs()) {
                rotated = Shapes.or(rotated, Shapes.box(1 - box.maxZ, box.minY, box.minX,
                        1 - box.minZ, box.maxY, box.maxX));
            }
            result[turn] = rotated.optimize();
        }
        return result;
    }
}
